function Metric({label,value,sub,icon:Icon,color}:{label:string,value:ReactNode,sub:ReactNode,icon:typeof Users,color?:string}){return <div className="metric"><span className="metric-label"><Icon size={17}/>{label}</span><strong style={color?{color}:undefined}>{value}</strong><span className="metric-sub">{sub}</span></div>}
