const lowestMastery=(p:Player)=>[...p.mastery].sort((a,b)=>(a.level-b.level)||(a.xp-b.xp))[0]?.champ??'';
const champTrainOptions=(p:Player)=>{const known=new Set(p.mastery.map(m=>m.champ));const full=known.size>=MASTERY_POOL;const ids=[...new Set([...known,...(full?[]:CHAMPIONS.filter(c=>c.role===p.role).map(c=>c.id))])];return ids.map(id=>{const lv=masteryLevel(p,id);return {id,name:`${champName(id)}${lv?` · Lv.${lv}`:known.has(id)?'':' · 신규 등록'}`};});};
