 async function next(){if(!g)return;if(g.phase==='PLAN'){nav('training');return;}if(['PREP','DRAFT','TACTICAL','RECAP'].includes(g.phase)){nav('match');return;}const type=g.phase==='MATCH_END'?'advance':g.phase==='SPLIT_END'?'nextSplit':g.phase==='WORLD_END'?'nextCompetition':'newSeason';const n=await act({type});if(n)nav(n.phase==='OFFSEASON'?'market':'home');}
 function exportSave(){if(!g)return;const data=JSON.stringify({format:'protocol-career-v1',exportedAt:new Date().toISOString(),...save},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`protocol-season-${g.season}-slot-${slot}.json`;a.click();URL.revokeObjectURL(url);toast.success('커리어 기록을 내보냈습니다.');}
